//! LiteSVM integration tests: the compiled SBF program (`deep_rewards.so`) with SPL Token,
//! Token-2022 and the ATA program (bundled with LiteSVM).
//!
//! Requires the `litesvm-tests` feature and `DEEP_REWARDS_SO` (target/deploy/deep_rewards.so);
//! `node scripts/programs-test.mjs --sbf` sets this up inside Docker.
//!
//! The multi-round scenarios replay fixtures/merkle-vectors.json, generated by the TypeScript
//! snapshot/allocation/tree code (packages/sdk/scripts/gen-rewards-fixtures.ts), so the off-chain
//! builder and the on-chain verifier are tested together.

use anchor_lang::prelude::{AccountDeserialize, Pubkey};
use anchor_lang::solana_program::instruction::{AccountMeta, Instruction};
use anchor_lang::solana_program::system_instruction;
use anchor_lang::{InstructionData, Space, ToAccountMetas};
use anchor_spl::associated_token::get_associated_token_address_with_program_id;
use anchor_spl::token_2022::spl_token_2022;
use deep_rewards::merkle::{leaf_hash, proof_of, root_of};
use deep_rewards::{
    accounts, instruction, ClaimStatus, Distributor, RewardsConfig, RewardsConfigParams,
    RewardsError, CLAIM_SEED, DISTRIBUTOR_SEED, HOLDER_VAULT_SEED, NATIVE_MINT,
    PENDING_CONFIG_SEED, REWARDS_CONFIG_SEED, WSOL_UNWRAP_SEED,
};
use litesvm::types::TransactionMetadata;
use litesvm::LiteSVM;
use serde_json::Value;
use solana_instruction_error::InstructionError;
use solana_keypair::Keypair;
use solana_signer::Signer;
use solana_transaction::Transaction;
use solana_transaction_error::TransactionError;
use std::collections::HashMap;
use std::str::FromStr;

const SOL: u64 = 1_000_000_000;
const TOKEN: Pubkey = anchor_spl::token::ID;
const TOKEN_2022: Pubkey = anchor_spl::token_2022::ID;
const ATA_PROGRAM: Pubkey = anchor_spl::associated_token::ID;
const SYSTEM: Pubkey = anchor_lang::system_program::ID;
const PYTH: Pubkey = deep_rewards::pyth::SOL_USD_PRICE_UPDATE;
const RECEIVER: Pubkey = deep_rewards::pyth::RECEIVER_PROGRAM_ID;
const FEED: [u8; 32] = deep_rewards::pyth::SOL_USD_FEED_ID;
const NOW: i64 = 1_900_000_000;
const DELAY: i64 = deep_rewards::MIN_ROOT_DELAY_SECONDS as i64;
/// RewardsConfig.stray_recipient in these tests.
const STRAY: Pubkey = Pubkey::new_from_array([0x5a; 32]);
const SLOT: u64 = 10_000;
const BPF_LOADER_UPGRADEABLE: Pubkey =
    Pubkey::from_str_const("BPFLoaderUpgradeab1e11111111111111111111111");

fn so_path(var: &str) -> String {
    std::env::var(var)
        .unwrap_or_else(|_| panic!("{var} is not set; run `node scripts/programs-test.mjs --sbf`"))
}

fn err(e: RewardsError) -> u32 {
    anchor_lang::error::ERROR_CODE_OFFSET + e as u32
}

fn config_pda() -> Pubkey {
    Pubkey::find_program_address(&[REWARDS_CONFIG_SEED], &deep_rewards::ID).0
}
fn holder_vault(mint: &Pubkey) -> Pubkey {
    Pubkey::find_program_address(&[HOLDER_VAULT_SEED, mint.as_ref()], &deep_rewards::ID).0
}
fn distributor_pda(mint: &Pubkey, reward_mint: &Pubkey) -> Pubkey {
    Pubkey::find_program_address(
        &[DISTRIBUTOR_SEED, mint.as_ref(), reward_mint.as_ref()],
        &deep_rewards::ID,
    )
    .0
}
fn claim_pda(dist: &Pubkey, claimant: &Pubkey) -> Pubkey {
    Pubkey::find_program_address(&[CLAIM_SEED, dist.as_ref(), claimant.as_ref()], &deep_rewards::ID).0
}
fn ata(owner: &Pubkey, mint: &Pubkey, program: &Pubkey) -> Pubkey {
    get_associated_token_address_with_program_id(owner, mint, program)
}

fn params(root_authority: Pubkey, stable: Vec<Pubkey>) -> RewardsConfigParams {
    RewardsConfigParams {
        root_authority,
        payout_mode: deep_rewards::PAYOUT_MODE_CLAIM,
        root_delay_seconds: deep_rewards::MIN_ROOT_DELAY_SECONDS,
        max_proof_len: 24,
        push_min_usd_micros: deep_rewards::DEFAULT_PUSH_MIN_USD_MICROS,
        min_holding_usd_micros: deep_rewards::DEFAULT_MIN_HOLDING_USD_MICROS,
        max_price_age_seconds: 120,
        sol_usd_price_update: PYTH,
        stable_mints: stable,
        stray_recipient: STRAY,
        guardian: guardian_kp().pubkey(),
    }
}

/// RewardsConfig.guardian in these tests: a key that is neither the admin nor the root
/// authority (unfunded until a test airdrops to it).
fn guardian_kp() -> Keypair {
    Keypair::new_from_array([0x47; 32])
}

fn pending_pda() -> Pubkey {
    Pubkey::find_program_address(&[PENDING_CONFIG_SEED], &deep_rewards::ID).0
}

/// Synthetic Pyth PriceUpdateV2 (same layout as programs/deep-curve/tests/litesvm.rs).
fn price_update_data(price: i64, conf: u64, expo: i32, publish: i64) -> Vec<u8> {
    let mut d = deep_rewards::pyth::PRICE_UPDATE_V2_DISCRIMINATOR.to_vec();
    d.extend_from_slice(&[9u8; 32]);
    d.push(1); // Full
    d.extend_from_slice(&FEED);
    d.extend_from_slice(&price.to_le_bytes());
    d.extend_from_slice(&conf.to_le_bytes());
    d.extend_from_slice(&expo.to_le_bytes());
    d.extend_from_slice(&publish.to_le_bytes());
    d.extend_from_slice(&(publish - 1).to_le_bytes());
    d.extend_from_slice(&price.to_le_bytes());
    d.extend_from_slice(&conf.to_le_bytes());
    d.extend_from_slice(&1234u64.to_le_bytes());
    d.push(0);
    d
}

#[derive(Clone, Copy)]
struct Dist {
    mint: Pubkey,
    reward_mint: Pubkey,
    program: Pubkey,
}

impl Dist {
    fn sol(mint: Pubkey) -> Self {
        Dist {
            mint,
            reward_mint: NATIVE_MINT,
            program: TOKEN,
        }
    }
    fn key(&self) -> Pubkey {
        distributor_pda(&self.mint, &self.reward_mint)
    }
    fn vault(&self) -> Pubkey {
        holder_vault(&self.mint)
    }
    fn token_vault(&self) -> Pubkey {
        ata(&self.vault(), &self.reward_mint, &self.program)
    }
    fn is_sol(&self) -> bool {
        self.reward_mint == NATIVE_MINT
    }
}

struct Env {
    svm: LiteSVM,
    admin: Keypair,
    root: Keypair,
    payer: Keypair,
}

impl Env {
    fn new(stable: Vec<Pubkey>) -> Self {
        let mut env = Self::new_uninitialized();
        let p = params(env.root.pubkey(), stable);
        let a = env.admin.insecure_clone();
        env.send(env.ix_initialize(&a.pubkey(), p), &[&a]).expect("initialize");
        env
    }

    fn new_uninitialized() -> Self {
        let admin = Keypair::new();
        let root = Keypair::new();
        let payer = Keypair::new();
        let mut svm = LiteSVM::new();
        svm.add_program_from_file(deep_rewards::ID, so_path("DEEP_REWARDS_SO"))
            .expect("load deep_rewards.so");
        // model a real deploy's upgrade authority (LiteSVM writes None)
        let pd = Pubkey::find_program_address(&[deep_rewards::ID.as_ref()], &BPF_LOADER_UPGRADEABLE).0;
        let mut acc = svm.get_account(&pd).expect("programdata");
        assert_eq!(&acc.data[0..4], &3u32.to_le_bytes());
        acc.data[12] = 1;
        acc.data[13..45].copy_from_slice(admin.pubkey().as_ref());
        svm.set_account(pd, acc).unwrap();
        // WSOL native mint
        let mut mint = vec![0u8; 82];
        mint[44] = 9;
        mint[45] = 1;
        let rent = svm.minimum_balance_for_rent_exemption(82);
        svm.set_account(
            NATIVE_MINT,
            solana_account::Account {
                lamports: rent,
                data: mint,
                owner: TOKEN,
                executable: false,
                rent_epoch: 0,
            },
        )
        .unwrap();
        for k in [&admin, &root, &payer] {
            svm.airdrop(&k.pubkey(), 100 * SOL).unwrap();
        }
        svm.warp_to_slot(SLOT);
        let mut env = Env {
            svm,
            admin,
            root,
            payer,
        };
        env.set_time(NOW);
        env
    }

    fn set_time(&mut self, t: i64) {
        let mut clock: anchor_lang::prelude::Clock = self.svm.get_sysvar();
        clock.unix_timestamp = t;
        self.svm.set_sysvar(&clock);
    }

    fn now(&self) -> i64 {
        let clock: anchor_lang::prelude::Clock = self.svm.get_sysvar();
        clock.unix_timestamp
    }

    fn advance(&mut self, secs: i64) {
        let t = self.now() + secs;
        self.set_time(t);
    }

    /// Writes a Pyth SOL/USD update published `age` seconds ago.
    fn set_price(&mut self, price: i64, age: i64) {
        let publish = self.now() - age;
        let data = price_update_data(price, (price as u64) / 1_000, -8, publish);
        let lamports = self.svm.minimum_balance_for_rent_exemption(data.len());
        self.svm
            .set_account(
                PYTH,
                solana_account::Account {
                    lamports,
                    data,
                    owner: RECEIVER,
                    executable: false,
                    rent_epoch: 0,
                },
            )
            .unwrap();
    }

    fn send(&mut self, ix: Instruction, signers: &[&Keypair]) -> Result<TransactionMetadata, u32> {
        self.send_ixs(vec![ix], signers)
    }

    /// signers[0] pays the fee. On failure returns the custom error code (or u32::MAX).
    fn send_ixs(&mut self, ixs: Vec<Instruction>, signers: &[&Keypair]) -> Result<TransactionMetadata, u32> {
        let tx = Transaction::new_signed_with_payer(
            &ixs,
            Some(&signers[0].pubkey()),
            signers,
            self.svm.latest_blockhash(),
        );
        let r = self.svm.send_transaction(tx);
        self.svm.expire_blockhash();
        r.map_err(|f| match f.err {
            TransactionError::InstructionError(_, InstructionError::Custom(c)) => c,
            other => {
                eprintln!("non-custom failure: {other:?}\n{}", f.meta.logs.join("\n"));
                u32::MAX
            }
        })
    }

    fn user(&mut self, lamports: u64) -> Keypair {
        let k = Keypair::new();
        if lamports > 0 {
            self.svm.airdrop(&k.pubkey(), lamports).unwrap();
        }
        k
    }

    fn lamports(&self, k: &Pubkey) -> u64 {
        self.svm.get_balance(k).unwrap_or(0)
    }

    fn load<T: AccountDeserialize>(&self, k: &Pubkey) -> T {
        let acc = self.svm.get_account(k).expect("account exists");
        T::try_deserialize(&mut acc.data.as_slice()).expect("deserialize")
    }

    fn token_amount(&self, account: &Pubkey) -> u64 {
        match self.svm.get_account(account) {
            Some(a) if a.data.len() >= 72 => u64::from_le_bytes(a.data[64..72].try_into().unwrap()),
            _ => 0,
        }
    }

    fn distributor(&self, d: &Dist) -> Distributor {
        self.load(&d.key())
    }

    fn rent(&self, len: usize) -> u64 {
        self.svm.minimum_balance_for_rent_exemption(len)
    }

    // ── SPL helpers ──

    fn create_mint(&mut self, mint: &Keypair, program: Pubkey, decimals: u8, freeze: bool) {
        let payer = self.payer.insecure_clone();
        let payer_key = payer.pubkey();
        let ixs = vec![
            system_instruction::create_account(&payer.pubkey(), &mint.pubkey(), self.rent(82), 82, &program),
            spl_token_2022::instruction::initialize_mint2(
                &program,
                &mint.pubkey(),
                &payer.pubkey(),
                if freeze { Some(&payer_key) } else { None },
                decimals,
            )
            .unwrap(),
        ];
        self.send_ixs(ixs, &[&payer, mint]).expect("create mint");
    }

    fn ix_create_ata(&self, payer: &Pubkey, owner: &Pubkey, mint: &Pubkey, program: &Pubkey) -> Instruction {
        Instruction {
            program_id: ATA_PROGRAM,
            accounts: vec![
                AccountMeta::new(*payer, true),
                AccountMeta::new(ata(owner, mint, program), false),
                AccountMeta::new_readonly(*owner, false),
                AccountMeta::new_readonly(*mint, false),
                AccountMeta::new_readonly(SYSTEM, false),
                AccountMeta::new_readonly(*program, false),
            ],
            data: vec![1], // CreateIdempotent
        }
    }

    /// Mints `amount` of `mint` (authority = payer) into a fresh holder ATA of `owner`.
    fn fund_tokens(&mut self, owner: &Pubkey, mint: &Pubkey, program: &Pubkey, amount: u64) -> Pubkey {
        let payer = self.payer.insecure_clone();
        let dest = ata(owner, mint, program);
        let ixs = vec![
            self.ix_create_ata(&payer.pubkey(), owner, mint, program),
            spl_token_2022::instruction::mint_to(program, mint, &dest, &payer.pubkey(), &[], amount).unwrap(),
        ];
        self.send_ixs(ixs, &[&payer]).expect("fund tokens");
        dest
    }

    // ── program instructions ──

    fn ix_initialize(&self, admin: &Pubkey, p: RewardsConfigParams) -> Instruction {
        Instruction {
            program_id: deep_rewards::ID,
            accounts: accounts::Initialize {
                admin: *admin,
                config: config_pda(),
                pending_config: pending_pda(),
                program: deep_rewards::ID,
                program_data: Pubkey::find_program_address(&[deep_rewards::ID.as_ref()], &BPF_LOADER_UPGRADEABLE).0,
                system_program: SYSTEM,
            }
            .to_account_metas(None),
            data: instruction::Initialize { params: p }.data(),
        }
    }

    fn ix_admin(&self, admin: &Pubkey, data: Vec<u8>) -> Instruction {
        Instruction {
            program_id: deep_rewards::ID,
            accounts: accounts::AdminOnly {
                admin: *admin,
                config: config_pda(),
            }
            .to_account_metas(None),
            data,
        }
    }

    fn ix_queue(&self, admin: &Pubkey, p: RewardsConfigParams) -> Instruction {
        Instruction {
            program_id: deep_rewards::ID,
            accounts: accounts::QueueConfigUpdate {
                admin: *admin,
                config: config_pda(),
                pending_config: pending_pda(),
            }
            .to_account_metas(None),
            data: instruction::QueueConfigUpdate { params: p }.data(),
        }
    }

    fn ix_apply(&self) -> Instruction {
        Instruction {
            program_id: deep_rewards::ID,
            accounts: accounts::ApplyConfigUpdate {
                config: config_pda(),
                pending_config: pending_pda(),
            }
            .to_account_metas(None),
            data: instruction::ApplyConfigUpdate {}.data(),
        }
    }

    fn ix_cancel(&self, admin: &Pubkey) -> Instruction {
        Instruction {
            program_id: deep_rewards::ID,
            accounts: accounts::CancelConfigUpdate {
                admin: *admin,
                config: config_pda(),
                pending_config: pending_pda(),
            }
            .to_account_metas(None),
            data: instruction::CancelConfigUpdate {}.data(),
        }
    }

    fn current_params(&self) -> RewardsConfigParams {
        let c: RewardsConfig = self.load(&config_pda());
        RewardsConfigParams {
            root_authority: c.root_authority,
            payout_mode: c.payout_mode,
            root_delay_seconds: c.root_delay_seconds,
            max_proof_len: c.max_proof_len,
            push_min_usd_micros: c.push_min_usd_micros,
            min_holding_usd_micros: c.min_holding_usd_micros,
            max_price_age_seconds: c.max_price_age_seconds,
            sol_usd_price_update: c.sol_usd_price_update,
            stable_mints: c.stable_mints[..c.stable_count as usize].to_vec(),
            stray_recipient: c.stray_recipient,
            guardian: c.guardian,
        }
    }

    fn ix_veto(&self, authority: &Pubkey, d: &Dist) -> Instruction {
        Instruction {
            program_id: deep_rewards::ID,
            accounts: accounts::VetoRoot {
                authority: *authority,
                config: config_pda(),
                distributor: d.key(),
            }
            .to_account_metas(None),
            data: instruction::VetoRoot {}.data(),
        }
    }

    fn ix_set_paused(&self, authority: &Pubkey, paused: bool) -> Instruction {
        Instruction {
            program_id: deep_rewards::ID,
            accounts: accounts::AdminOrGuardian {
                authority: *authority,
                config: config_pda(),
            }
            .to_account_metas(None),
            data: instruction::SetPaused { paused }.data(),
        }
    }

    fn ix_migrate(&self, payer: &Pubkey) -> Instruction {
        Instruction {
            program_id: deep_rewards::ID,
            accounts: accounts::MigrateConfig {
                payer: *payer,
                config: config_pda(),
                pending_config: pending_pda(),
                system_program: SYSTEM,
            }
            .to_account_metas(None),
            data: instruction::MigrateConfig {}.data(),
        }
    }

    /// queue → wait the delay → apply (permissionless), as governance must.
    fn update_config(&mut self, p: RewardsConfigParams) {
        let a = self.admin.insecure_clone();
        let ix = self.ix_queue(&a.pubkey(), p);
        self.send(ix, &[&a]).expect("queue_config_update");
        let delay = self.load::<RewardsConfig>(&config_pda()).root_delay_seconds as i64;
        self.advance(delay);
        let anyone = self.user(SOL);
        let ix = self.ix_apply();
        self.send(ix, &[&anyone]).expect("apply_config_update");
    }

    fn set_mode(&mut self, mode: u8) {
        let mut p = self.current_params();
        p.payout_mode = mode;
        self.update_config(p);
    }

    fn ix_init_distributor(&self, authority: &Pubkey, d: &Dist) -> Instruction {
        Instruction {
            program_id: deep_rewards::ID,
            accounts: accounts::InitDistributor {
                authority: *authority,
                config: config_pda(),
                mint: d.mint,
                reward_mint: d.reward_mint,
                holder_vault: d.vault(),
                distributor: d.key(),
                vault_token_account: d.token_vault(),
                reward_token_program: d.program,
                associated_token_program: ATA_PROGRAM,
                system_program: SYSTEM,
            }
            .to_account_metas(None),
            data: instruction::InitDistributor {}.data(),
        }
    }

    fn init_distributor(&mut self, d: &Dist) {
        let r = self.root.insecure_clone();
        let ix = self.ix_init_distributor(&r.pubkey(), d);
        self.send(ix, &[&r]).expect("init_distributor");
    }

    /// Deposits through the program's `deposit_*` (SOL from a fresh depositor; tokens minted to
    /// a depositor first).
    fn deposit(&mut self, d: &Dist, amount: u64) {
        if amount == 0 {
            return;
        }
        if d.is_sol() {
            let dep = self.user(amount + SOL);
            let ix = Instruction {
                program_id: deep_rewards::ID,
                accounts: accounts::DepositSol {
                    depositor: dep.pubkey(),
                    distributor: d.key(),
                    holder_vault: d.vault(),
                    system_program: SYSTEM,
                }
                .to_account_metas(None),
                data: instruction::DepositSol { amount }.data(),
            };
            self.send(ix, &[&dep]).expect("deposit_sol");
        } else {
            let dep = self.user(SOL);
            let from = self.fund_tokens(&dep.pubkey(), &d.reward_mint, &d.program, amount);
            let ix = Instruction {
                program_id: deep_rewards::ID,
                accounts: accounts::DepositToken {
                    depositor: dep.pubkey(),
                    distributor: d.key(),
                    reward_mint: d.reward_mint,
                    depositor_token: from,
                    token_vault: d.token_vault(),
                    token_program: d.program,
                }
                .to_account_metas(None),
                data: instruction::DepositToken { amount }.data(),
            };
            self.send(ix, &[&dep]).expect("deposit_token");
        }
    }

    fn ix_propose(&self, signer: &Pubkey, d: &Dist, root: [u8; 32], max: u64, slot: u64, hash: [u8; 32]) -> Instruction {
        Instruction {
            program_id: deep_rewards::ID,
            accounts: accounts::ProposeRoot {
                root_authority: *signer,
                config: config_pda(),
                distributor: d.key(),
                holder_vault: d.vault(),
                token_vault: d.token_vault(),
            }
            .to_account_metas(None),
            data: instruction::ProposeRoot {
                root,
                max_total_claim: max,
                snapshot_slot: slot,
                data_hash: hash,
            }
            .data(),
        }
    }

    /// propose_root only (the root stays pending for the delay).
    fn propose_pending(&mut self, d: &Dist, root: [u8; 32], max: u64, slot: u64) -> Result<TransactionMetadata, u32> {
        let r = self.root.insecure_clone();
        let ix = self.ix_propose(&r.pubkey(), d, root, max, slot, [3; 32]);
        self.send(ix, &[&r])
    }

    fn ix_activate(&self, d: &Dist) -> Instruction {
        Instruction {
            program_id: deep_rewards::ID,
            accounts: accounts::ActivateRoot {
                distributor: d.key(),
                holder_vault: d.vault(),
                token_vault: d.token_vault(),
            }
            .to_account_metas(None),
            data: instruction::ActivateRoot {}.data(),
        }
    }

    /// propose_root, wait out the (≥ 1 h) delay, then the permissionless activate_root.
    fn propose(&mut self, d: &Dist, root: [u8; 32], max: u64, slot: u64) -> Result<TransactionMetadata, u32> {
        let meta = self.propose_pending(d, root, max, slot)?;
        if self.distributor(d).has_pending {
            let delay = self.load::<RewardsConfig>(&config_pda()).root_delay_seconds as i64;
            self.advance(delay);
            let anyone = self.user(SOL);
            let ix = self.ix_activate(d);
            return self.send(ix, &[&anyone]);
        }
        Ok(meta)
    }

    fn ix_claim(&self, claimant: &Pubkey, d: &Dist, cumulative: u64, proof: Vec<[u8; 32]>) -> Instruction {
        let status = claim_pda(&d.key(), claimant);
        if d.is_sol() {
            Instruction {
                program_id: deep_rewards::ID,
                accounts: accounts::ClaimSol {
                    claimant: *claimant,
                    config: config_pda(),
                    distributor: d.key(),
                    holder_vault: d.vault(),
                    claim_status: status,
                    system_program: SYSTEM,
                }
                .to_account_metas(None),
                data: instruction::ClaimSol { cumulative_amount: cumulative, proof }.data(),
            }
        } else {
            Instruction {
                program_id: deep_rewards::ID,
                accounts: accounts::ClaimToken {
                    claimant: *claimant,
                    config: config_pda(),
                    distributor: d.key(),
                    holder_vault: d.vault(),
                    reward_mint: d.reward_mint,
                    token_vault: d.token_vault(),
                    claimant_token: ata(claimant, &d.reward_mint, &d.program),
                    claim_status: status,
                    token_program: d.program,
                    system_program: SYSTEM,
                }
                .to_account_metas(None),
                data: instruction::ClaimToken { cumulative_amount: cumulative, proof }.data(),
            }
        }
    }

    /// The claimant signs (and pays its ClaimStatus rent); `self.payer` pays the tx fee, so
    /// the claimant's balance changes only by the payout (and the one-time rent).
    fn claim(&mut self, claimant: &Keypair, d: &Dist, cumulative: u64, proof: Vec<[u8; 32]>) -> Result<TransactionMetadata, u32> {
        let mut ixs = vec![];
        if !d.is_sol() {
            ixs.push(self.ix_create_ata(&self.payer.pubkey(), &claimant.pubkey(), &d.reward_mint, &d.program));
        }
        ixs.push(self.ix_claim(&claimant.pubkey(), d, cumulative, proof));
        let p = self.payer.insecure_clone();
        self.send_ixs(ixs, &[&p, claimant])
    }

    fn ix_push(&self, cranker: &Pubkey, claimant: &Pubkey, d: &Dist, cumulative: u64, proof: Vec<[u8; 32]>) -> Instruction {
        let status = claim_pda(&d.key(), claimant);
        if d.is_sol() {
            Instruction {
                program_id: deep_rewards::ID,
                accounts: accounts::PushSol {
                    cranker: *cranker,
                    config: config_pda(),
                    distributor: d.key(),
                    holder_vault: d.vault(),
                    claimant: *claimant,
                    claim_status: status,
                    price_update: PYTH,
                    system_program: SYSTEM,
                }
                .to_account_metas(None),
                data: instruction::PushSol { cumulative_amount: cumulative, proof }.data(),
            }
        } else {
            Instruction {
                program_id: deep_rewards::ID,
                accounts: accounts::PushToken {
                    cranker: *cranker,
                    config: config_pda(),
                    distributor: d.key(),
                    holder_vault: d.vault(),
                    reward_mint: d.reward_mint,
                    token_vault: d.token_vault(),
                    claimant: *claimant,
                    claimant_token: ata(claimant, &d.reward_mint, &d.program),
                    claim_status: status,
                    token_program: d.program,
                    associated_token_program: ATA_PROGRAM,
                    system_program: SYSTEM,
                }
                .to_account_metas(None),
                data: instruction::PushToken { cumulative_amount: cumulative, proof }.data(),
            }
        }
    }

    fn push(&mut self, cranker: &Keypair, claimant: &Pubkey, d: &Dist, cumulative: u64, proof: Vec<[u8; 32]>) -> Result<TransactionMetadata, u32> {
        let ix = self.ix_push(&cranker.pubkey(), claimant, d, cumulative, proof);
        self.send(ix, &[cranker])
    }

    /// Funds the vault can still pay (SOL above the reserve, or the token vault balance).
    fn available(&self, d: &Dist) -> u64 {
        if d.is_sol() {
            self.lamports(&d.vault()) - self.distributor(d).vault_reserve
        } else {
            self.token_amount(&d.token_vault())
        }
    }

    /// What `who` has received from the distributor (lamports or token units).
    fn received(&self, who: &Pubkey, d: &Dist) -> u64 {
        if d.is_sol() {
            self.lamports(who)
        } else {
            self.token_amount(&ata(who, &d.reward_mint, &d.program))
        }
    }
}

/// A SOL holder mint (SPL Token, 6 decimals) and its initialised SOL distributor.
fn sol_setup(env: &mut Env) -> Dist {
    let mint = Keypair::new();
    env.create_mint(&mint, TOKEN, 6, false);
    let d = Dist::sol(mint.pubkey());
    env.init_distributor(&d);
    d
}

/// Tree helper: (claimant, cumulative) → (root, total, proofs by claimant)
fn tree(d: &Dist, entries: &[(Pubkey, u64)]) -> ([u8; 32], u64, HashMap<Pubkey, Vec<[u8; 32]>>) {
    let leaves: Vec<[u8; 32]> = entries.iter().map(|(c, a)| leaf_hash(&d.key(), c, *a)).collect();
    let mut proofs = HashMap::new();
    for (i, (c, _)) in entries.iter().enumerate() {
        proofs.insert(*c, proof_of(&leaves, i));
    }
    (root_of(&leaves).unwrap(), entries.iter().map(|e| e.1).sum(), proofs)
}

