fn fixtures() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/merkle-vectors.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}
fn pk(v: &Value) -> Pubkey {
    Pubkey::from_str(v.as_str().unwrap()).unwrap()
}
fn h32(v: &Value) -> [u8; 32] {
    let s = v.as_str().unwrap();
    let mut out = [0u8; 32];
    for (i, b) in out.iter_mut().enumerate() {
        *b = u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).unwrap();
    }
    out
}
fn u(v: &Value) -> u64 {
    v.as_str().unwrap().parse().unwrap()
}
fn kp_from_seed(v: &Value) -> Keypair {
    Keypair::new_from_array(h32(v))
}

/// Replays a fixture scenario on chain: per round deposit → propose the fixture root → the
/// listed claims; then every holder claims what is left. Asserts every payout to the unit and
/// that the vault ends with exactly the carried dust (sum of claims == deposits − dust).
fn replay(env: &mut Env, s: &Value, d: &Dist, mut between: impl FnMut(&mut Env, usize, &Value) -> u64) {
    let holders: HashMap<Pubkey, Keypair> = s["holders"]
        .as_array()
        .unwrap()
        .iter()
        .map(|h| {
            let k = kp_from_seed(&h["seed"]);
            assert_eq!(k.pubkey(), pk(&h["pubkey"]), "TS/Rust keypair derivation");
            (k.pubkey(), k)
        })
        .collect();
    for (_, k) in holders.iter() {
        env.svm.airdrop(&k.pubkey(), SOL).unwrap();
    }
    let excluded: Vec<Pubkey> = s["excludedOwners"].as_object().unwrap().values().map(pk).collect();
    let mut claimed: HashMap<Pubkey, u64> = HashMap::new();
    let mut deposited = 0u64;
    let mut paid_total = 0u64;
    let mut last: Option<(Vec<(Pubkey, u64, Vec<[u8; 32]>)>, u64)> = None;
    for (i, r) in s["rounds"].as_array().unwrap().iter().enumerate() {
        let dep = u(&r["deposit"]);
        env.deposit(d, dep);
        deposited += dep;
        // the pool the TS job saw is exactly what the chain says is unallocated
        let dist = env.distributor(d);
        assert_eq!(
            env.available(d) - (dist.max_total_claim - dist.total_claimed),
            u(&r["pool"]),
            "round {i}: unallocated on chain == fixture pool"
        );
        env.propose(d, h32(&r["root"]), u(&r["maxTotalClaim"]), u(&r["snapshotSlot"]))
            .unwrap_or_else(|e| panic!("propose round {i}: {e}"));
        let dist = env.distributor(d);
        assert_eq!(dist.round as usize, i + 1);
        assert_eq!(dist.max_total_claim, u(&r["maxTotalClaim"]));
        let leaves: Vec<(Pubkey, u64, Vec<[u8; 32]>)> = r["leaves"]
            .as_array()
            .unwrap()
            .iter()
            .map(|l| {
                (
                    pk(&l["claimant"]),
                    u(&l["cumulative"]),
                    l["proof"].as_array().unwrap().iter().map(h32).collect(),
                )
            })
            .collect();
        // excluded (program-owned) owners never have a leaf: their share went to real holders
        for x in &excluded {
            assert!(leaves.iter().all(|l| l.0 != *x), "excluded owner {x} in tree");
        }
        assert_eq!(
            u(&r["allocatedTotal"]) + u(&r["dust"]),
            u(&r["pool"]),
            "the whole pool is allocated to eligible holders except dust"
        );
        paid_total += between(env, i, r); // pushes made between root and claims
        for who in r["claims"].as_array().unwrap().iter().map(pk) {
            let (_, cum, proof) = leaves.iter().find(|l| l.0 == who).expect("claimant leaf").clone();
            let before = env.received(&who, d);
            let status_existed = env.svm.get_account(&claim_pda(&d.key(), &who)).is_some();
            let already = env
                .svm
                .get_account(&claim_pda(&d.key(), &who))
                .map(|_| env.load::<ClaimStatus>(&claim_pda(&d.key(), &who)).claimed)
                .unwrap_or(0);
            if cum == already {
                continue; // pushed earlier in this round
            }
            env.claim(&holders[&who], d, cum, proof).unwrap_or_else(|e| panic!("claim {who}: {e}"));
            let rent = if d.is_sol() && !status_existed { env.rent(8 + ClaimStatus::INIT_SPACE) } else { 0 };
            assert_eq!(env.received(&who, d) + rent - before, cum - already, "exact payout");
            paid_total += cum - already;
            claimed.insert(who, cum);
        }
        last = Some((leaves, u(&r["dust"])));
    }
    // everyone claims the rest
    let (leaves, final_dust) = last.unwrap();
    for (who, cum, proof) in leaves {
        let already = env
            .svm
            .get_account(&claim_pda(&d.key(), &who))
            .map(|_| env.load::<ClaimStatus>(&claim_pda(&d.key(), &who)).claimed)
            .unwrap_or(0);
        if already == cum {
            continue;
        }
        env.claim(&holders[&who], d, cum, proof.clone()).unwrap();
        paid_total += cum - already;
        // a second claim of the same leaf pays nothing
        assert_eq!(
            env.claim(&holders[&who], d, cum, proof),
            Err(err(RewardsError::NothingToClaim))
        );
    }
    let dist = env.distributor(d);
    assert_eq!(dist.total_claimed, dist.max_total_claim, "everything owed was paid");
    assert_eq!(dist.total_claimed, paid_total);
    assert_eq!(paid_total + final_dust, deposited, "claims + carried dust == deposits");
    assert_eq!(env.available(d), final_dust, "vault drained exactly to the carried dust");
    if d.is_sol() {
        assert_eq!(env.lamports(&d.vault()), dist.vault_reserve + final_dust);
    }
}

