#[test]
fn lamports_credited_before_init_stay_distributable() {
    // Phase 2–3 may credit the holder vault before the distributor exists (a plain lamport
    // credit, at least the rent minimum). init_distributor's payer funds the reserve ON TOP,
    // so every credited lamport is paid to holders.
    let mut env = Env::new(vec![]);
    let mint = Keypair::new();
    env.create_mint(&mint, TOKEN, 6, false);
    let d = Dist::sol(mint.pubkey());
    let early = env.rent(0) + 12_345;
    env.svm.airdrop(&d.vault(), early).unwrap();
    env.init_distributor(&d);
    assert_eq!(env.distributor(&d).vault_reserve, env.rent(0));
    assert_eq!(env.available(&d), early);
    let h = env.user(SOL);
    let (root, total, proofs) = tree(&d, &[(h.pubkey(), early)]);
    env.propose(&d, root, total, 50).unwrap();
    env.claim(&h, &d, early, proofs[&h.pubkey()].clone()).unwrap();
    assert_eq!(env.available(&d), 0);
    assert_eq!(env.lamports(&d.vault()), env.rent(0), "only the reserve is left");
}

#[test]
fn token2022_scenario_claims_and_push_with_ata_creation() {
    let f = fixtures();
    let s = &f["scenarios"]["token2022"];
    let reward_kp = kp_from_seed(&s["rewardMintSeed"]);
    assert_eq!(reward_kp.pubkey(), pk(&s["rewardMint"]));
    let mut env = Env::new(vec![reward_kp.pubkey()]);
    let mint = kp_from_seed(&s["mintSeed"]);
    env.create_mint(&mint, TOKEN, 6, false);
    env.create_mint(&reward_kp, TOKEN_2022, 6, false);
    let d = Dist {
        mint: mint.pubkey(),
        reward_mint: reward_kp.pubkey(),
        program: TOKEN_2022,
    };
    assert_eq!(d.key(), pk(&s["distributor"]));
    env.init_distributor(&d);
    assert_eq!(env.distributor(&d).vault_reserve, 0);
    let holder1 = pk(&s["holders"][1]["pubkey"]);
    let holder2 = pk(&s["holders"][2]["pubkey"]);
    replay(&mut env, s, &d, |env, i, r| {
        if i != 0 {
            return 0;
        }
        let leaf = |who: &Pubkey| -> (u64, Vec<[u8; 32]>) {
            let l = r["leaves"].as_array().unwrap().iter().find(|l| pk(&l["claimant"]) == *who).unwrap();
            (u(&l["cumulative"]), l["proof"].as_array().unwrap().iter().map(h32).collect())
        };
        let cranker = env.user(SOL);
        let (c1, p1) = leaf(&holder1);
        // CLAIM mode: pushes are refused
        assert_eq!(
            env.push(&cranker, &holder1, &d, c1, p1.clone()).map(|_| ()),
            Err(err(RewardsError::PushDisabled))
        );
        env.set_mode(deep_rewards::PAYOUT_MODE_AUTO_SEND);
        // holder-2's ~$2.4 is below the $20 threshold: refused, stays claimable
        let (c2, p2) = leaf(&holder2);
        assert!(c2 < 20_000_000);
        assert_eq!(
            env.push(&cranker, &holder2, &d, c2, p2).map(|_| ()),
            Err(err(RewardsError::BelowPushThreshold))
        );
        assert!(env.svm.get_account(&claim_pda(&d.key(), &holder2)).is_none());
        // holder-1 has no ATA: the push creates it (cranker pays) and pays exactly c1
        assert!(c1 >= 20_000_000);
        assert!(env.svm.get_account(&ata(&holder1, &d.reward_mint, &d.program)).is_none());
        env.push(&cranker, &holder1, &d, c1, p1.clone()).expect("push");
        assert_eq!(env.received(&holder1, &d), c1);
        let st: ClaimStatus = env.load(&claim_pda(&d.key(), &holder1));
        assert_eq!((st.claimed, st.payer), (c1, cranker.pubkey()));
        // pushing again pays nothing
        assert_eq!(
            env.push(&cranker, &holder1, &d, c1, p1).map(|_| ()),
            Err(err(RewardsError::NothingToClaim))
        );
        env.set_mode(deep_rewards::PAYOUT_MODE_CLAIM);
        c1
    });
}

#[test]
fn claim_exact_double_claim_wrong_proof_and_proof_length() {
    let mut env = Env::new(vec![]);
    let d = sol_setup(&mut env);
    let (a, b, c) = (env.user(SOL), env.user(SOL), env.user(SOL));
    env.deposit(&d, 3 * SOL);
    let entries = [(a.pubkey(), SOL), (b.pubkey(), 2 * SOL - 1)];
    let (root, total, proofs) = tree(&d, &entries);
    // nothing claimable before a root exists
    assert_eq!(
        env.claim(&a, &d, SOL, proofs[&a.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::NoRoot))
    );
    env.propose(&d, root, total, 100).unwrap();
    // wrong amount, someone else's proof, another wallet using a's leaf: all InvalidProof
    assert_eq!(
        env.claim(&a, &d, SOL + 1, proofs[&a.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::InvalidProof))
    );
    assert_eq!(
        env.claim(&a, &d, SOL, proofs[&b.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::InvalidProof))
    );
    assert_eq!(
        env.claim(&c, &d, SOL, proofs[&a.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::InvalidProof))
    );
    // a proof longer than the cap is refused before hashing
    assert_eq!(
        env.claim(&a, &d, SOL, vec![[0u8; 32]; 25]).map(|_| ()),
        Err(err(RewardsError::ProofTooLong))
    );
    // exact payout: claimant receives SOL minus only its one-time ClaimStatus rent
    let a0 = env.lamports(&a.pubkey());
    let v0 = env.lamports(&d.vault());
    let meta = env.claim(&a, &d, SOL, proofs[&a.pubkey()].clone()).unwrap();
    println!("claim_sol CU (1-level proof): {}", meta.compute_units_consumed);
    let rent = env.rent(8 + ClaimStatus::INIT_SPACE);
    assert_eq!(env.lamports(&a.pubkey()), a0 + SOL - rent);
    assert_eq!(env.lamports(&d.vault()), v0 - SOL);
    // double claim
    assert_eq!(
        env.claim(&a, &d, SOL, proofs[&a.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::NothingToClaim))
    );
    assert_eq!(env.distributor(&d).total_claimed, SOL);
    // paused: roots stop, claims never do
    let adm = env.admin.insecure_clone();
    let ix = env.ix_admin(&adm.pubkey(), instruction::SetPaused { paused: true }.data());
    env.send(ix, &[&adm]).unwrap();
    assert_eq!(env.propose(&d, root, total, 101).map(|_| ()), Err(err(RewardsError::Paused)));
    env.claim(&b, &d, 2 * SOL - 1, proofs[&b.pubkey()].clone()).expect("claim while paused");
}

#[test]
fn deep_proof_claim_compute_units() {
    // 2^17 leaves would need 17 siblings; build a 17-level path by hand: the root is folded
    // from the leaf with 17 arbitrary siblings (the program only folds and compares).
    let mut env = Env::new(vec![]);
    let d = sol_setup(&mut env);
    let a = env.user(SOL);
    env.deposit(&d, SOL);
    let leaf = leaf_hash(&d.key(), &a.pubkey(), SOL);
    let proof: Vec<[u8; 32]> = (0..17u8).map(|i| [i + 1; 32]).collect();
    let mut root = leaf;
    for p in &proof {
        root = deep_rewards::merkle::node_hash(&root, p);
    }
    env.propose(&d, root, SOL, 100).unwrap();
    let meta = env.claim(&a, &d, SOL, proof).unwrap();
    println!("claim_sol CU (17-level proof, first claim): {}", meta.compute_units_consumed);
    assert!(meta.compute_units_consumed < 60_000);
}

#[test]
fn roots_are_funded_monotonic_fresh_and_only_from_the_root_authority() {
    let mut env = Env::new(vec![]);
    let d = sol_setup(&mut env);
    let a = env.user(SOL);
    env.deposit(&d, SOL);
    let (root, _, _) = tree(&d, &[(a.pubkey(), SOL + 1)]);
    // promises more than the vault holds
    assert_eq!(env.propose(&d, root, SOL + 1, 100).map(|_| ()), Err(err(RewardsError::RootUnfunded)));
    let (root, total, proofs) = tree(&d, &[(a.pubkey(), SOL / 2)]);
    // not the root authority (admin included)
    let adm = env.admin.insecure_clone();
    let ix = env.ix_propose(&adm.pubkey(), &d, root, total, 100, [0; 32]);
    assert!(env.send(ix, &[&adm]).is_err());
    // future snapshot slot
    assert_eq!(env.propose(&d, root, total, SLOT + 1).map(|_| ()), Err(err(RewardsError::StaleSnapshot)));
    env.propose(&d, root, total, 100).unwrap();
    // same or older snapshot slot
    assert_eq!(env.propose(&d, root, total, 100).map(|_| ()), Err(err(RewardsError::StaleSnapshot)));
    // lower total than the active root
    let (r2, _, _) = tree(&d, &[(a.pubkey(), SOL / 4)]);
    assert_eq!(env.propose(&d, r2, SOL / 4, 101).map(|_| ()), Err(err(RewardsError::RootNotMonotonic)));
    // root delay: pending → not ready → veto → nothing pending → re-propose → activate
    let (r3, t3, _) = tree(&d, &[(a.pubkey(), SOL)]);
    env.propose_pending(&d, r3, t3, 102).unwrap();
    let dist = env.distributor(&d);
    assert!(dist.has_pending);
    assert_eq!(dist.round, 1, "still the first root");
    let activate = env.ix_activate(&d);
    let anyone = env.user(SOL);
    assert_eq!(env.send(activate.clone(), &[&anyone]).map(|_| ()), Err(err(RewardsError::RootNotReady)));
    let veto = env.ix_veto(&adm.pubkey(), &d);
    let v0 = env.lamports(&d.vault());
    env.send(veto.clone(), &[&adm]).unwrap();
    assert_eq!(env.lamports(&d.vault()), v0, "a veto moves no funds");
    assert_eq!(env.send(veto, &[&adm]).map(|_| ()), Err(err(RewardsError::NoPendingRoot)));
    // the old root stays claimable throughout
    env.claim(&a, &d, SOL / 2, proofs[&a.pubkey()].clone()).unwrap();
    env.propose_pending(&d, r3, t3, 103).unwrap();
    env.advance(DELAY - 1);
    assert_eq!(env.send(activate.clone(), &[&anyone]).map(|_| ()), Err(err(RewardsError::RootNotReady)));
    env.advance(1);
    env.send(activate, &[&anyone]).expect("permissionless activation after eta");
    let dist = env.distributor(&d);
    assert_eq!((dist.round, dist.max_total_claim, dist.has_pending), (2, SOL, false));
}

#[test]
fn push_sol_threshold_price_and_recipient_checks() {
    let mut env = Env::new(vec![]);
    let d = sol_setup(&mut env);
    let rich = Keypair::new(); // no account yet: a push creates it (≥ rent)
    let small = env.user(SOL);
    let token_acct = env.fund_tokens(&small.pubkey(), &d.mint, &TOKEN, 1); // program-owned
    env.deposit(&d, 2 * SOL);
    let entries = [(rich.pubkey(), SOL / 10), (small.pubkey(), SOL / 20), (token_acct, SOL / 10)];
    let (root, total, proofs) = tree(&d, &entries);
    env.propose(&d, root, total, 100).unwrap();
    let cranker = env.user(SOL);
    assert_eq!(
        env.push(&cranker, &rich.pubkey(), &d, SOL / 10, proofs[&rich.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::PushDisabled))
    );
    env.set_mode(deep_rewards::PAYOUT_MODE_AUTO_SEND);
    // no price account / stale price: refused
    assert_eq!(
        env.push(&cranker, &rich.pubkey(), &d, SOL / 10, proofs[&rich.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::PriceInvalid))
    );
    env.set_price(20_000_000_000, 500); // $200, 500 s old > 120 s
    assert_eq!(
        env.push(&cranker, &rich.pubkey(), &d, SOL / 10, proofs[&rich.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::PriceInvalid))
    );
    env.set_price(20_000_000_000, 5);
    // 0.05 SOL at $200 = $10 < $20
    assert_eq!(
        env.push(&cranker, &small.pubkey(), &d, SOL / 20, proofs[&small.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::BelowPushThreshold))
    );
    // a token account (program-owned) is never a push recipient: stays claimable by nobody
    // else, nothing moves
    let v0 = env.lamports(&d.vault());
    assert_eq!(
        env.push(&cranker, &token_acct, &d, SOL / 10, proofs[&token_acct].clone()).map(|_| ()),
        Err(err(RewardsError::RecipientNotEligible))
    );
    assert_eq!(env.lamports(&d.vault()), v0);
    // 0.1 SOL at $200 = $20: pushed exactly; the cranker pays the ClaimStatus rent
    let c0 = env.lamports(&cranker.pubkey());
    let meta = env.push(&cranker, &rich.pubkey(), &d, SOL / 10, proofs[&rich.pubkey()].clone()).unwrap();
    println!("push_sol CU: {}", meta.compute_units_consumed);
    assert_eq!(env.lamports(&rich.pubkey()), SOL / 10);
    assert_eq!(env.lamports(&d.vault()), v0 - SOL / 10);
    assert!(env.lamports(&cranker.pubkey()) < c0);
    // the holder can still claim anything a later root adds; pushing twice pays nothing
    assert_eq!(
        env.push(&cranker, &rich.pubkey(), &d, SOL / 10, proofs[&rich.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::NothingToClaim))
    );
    // paused stops pushes
    let adm = env.admin.insecure_clone();
    let ix = env.ix_admin(&adm.pubkey(), instruction::SetPaused { paused: true }.data());
    env.send(ix, &[&adm]).unwrap();
    assert_eq!(
        env.push(&cranker, &small.pubkey(), &d, SOL / 20, proofs[&small.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::Paused))
    );
    // ...but the small holder simply claims
    env.claim(&small, &d, SOL / 20, proofs[&small.pubkey()].clone()).unwrap();
}

#[test]
fn push_token_refuses_frozen_recipient_and_non_stable_assets() {
    // a stable (face-valued) Token-2022 quote mint with a freeze authority
    let usd = Keypair::new();
    let mut env = Env::new(vec![usd.pubkey()]);
    let mint = Keypair::new();
    env.create_mint(&mint, TOKEN, 6, false);
    env.create_mint(&usd, TOKEN_2022, 6, true);
    let d = Dist {
        mint: mint.pubkey(),
        reward_mint: usd.pubkey(),
        program: TOKEN_2022,
    };
    env.init_distributor(&d);
    env.deposit(&d, 100_000_000);
    let frozen = env.user(SOL);
    let fresh = Keypair::new();
    let (root, total, proofs) = tree(&d, &[(frozen.pubkey(), 30_000_000), (fresh.pubkey(), 25_000_000)]);
    env.propose(&d, root, total, 100).unwrap();
    env.set_mode(deep_rewards::PAYOUT_MODE_AUTO_SEND);
    // freeze the frozen holder's ATA
    let payer = env.payer.insecure_clone();
    let fa = env.fund_tokens(&frozen.pubkey(), &usd.pubkey(), &TOKEN_2022, 0);
    let ix = spl_token_2022::instruction::freeze_account(&TOKEN_2022, &fa, &usd.pubkey(), &payer.pubkey(), &[]).unwrap();
    env.send(ix, &[&payer]).unwrap();
    let cranker = env.user(SOL);
    let v0 = env.token_amount(&d.token_vault());
    assert_eq!(
        env.push(&cranker, &frozen.pubkey(), &d, 30_000_000, proofs[&frozen.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::RecipientFrozen))
    );
    assert_eq!(env.token_amount(&d.token_vault()), v0, "nothing moved");
    assert!(env.svm.get_account(&claim_pda(&d.key(), &frozen.pubkey())).is_none(), "still claimable");
    // ATA does not exist yet: created idempotently, exact amount
    env.push(&cranker, &fresh.pubkey(), &d, 25_000_000, proofs[&fresh.pubkey()].clone()).unwrap();
    assert_eq!(env.received(&fresh.pubkey(), &d), 25_000_000);
    // admin removes the mint from the stable list: that asset is claim-only now
    let mut p = env.current_params();
    p.stable_mints = vec![];
    env.update_config(p);
    assert_eq!(
        env.push(&cranker, &frozen.pubkey(), &d, 30_000_000, proofs[&frozen.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::PushUnsupportedAsset))
    );
}

#[test]
fn unwrap_wsol_moves_deepswap_wsol_into_the_vault_and_refunds_the_payer() {
    let mut env = Env::new(vec![]);
    let d = sol_setup(&mut env);
    let wsol = d.token_vault();
    assert!(env.svm.get_account(&wsol).is_some(), "init created the vault's WSOL ATA");
    // DeepSwap's reward collection lands as WSOL: simulate with a transfer + sync_native
    let donor = env.user(5 * SOL);
    let ixs = vec![
        system_instruction::transfer(&donor.pubkey(), &wsol, 3 * SOL),
        anchor_spl::token::spl_token::instruction::sync_native(&TOKEN, &wsol).unwrap(),
    ];
    env.send_ixs(ixs, &[&donor]).unwrap();
    assert_eq!(env.token_amount(&wsol), 3 * SOL);
    let av0 = env.available(&d);
    let payer = env.user(SOL);
    let p0 = env.lamports(&payer.pubkey());
    let ix = Instruction {
        program_id: deep_rewards::ID,
        accounts: accounts::UnwrapWsol {
            payer: payer.pubkey(),
            distributor: d.key(),
            holder_vault: d.vault(),
            wsol_vault: wsol,
            wsol_unwrap: Pubkey::find_program_address(&[WSOL_UNWRAP_SEED, d.key().as_ref()], &deep_rewards::ID).0,
            wsol_mint: NATIVE_MINT,
            token_program: TOKEN,
            system_program: SYSTEM,
        }
        .to_account_metas(None),
        data: instruction::UnwrapWsol {}.data(),
    };
    env.send(ix.clone(), &[&payer]).unwrap();
    assert_eq!(env.available(&d), av0 + 3 * SOL, "every WSOL lamport is now distributable");
    assert_eq!(env.token_amount(&wsol), 0);
    assert!(env.svm.get_account(&wsol).is_some(), "the ATA stays for deep-amm");
    assert_eq!(env.lamports(&payer.pubkey()), p0 - 5_000, "payer refunded, pays only the fee");
    let tmp = Pubkey::find_program_address(&[WSOL_UNWRAP_SEED, d.key().as_ref()], &deep_rewards::ID).0;
    assert_eq!(env.lamports(&tmp), 0, "temporary account closed");
    assert_eq!(env.send(ix, &[&payer]).map(|_| ()), Err(err(RewardsError::ZeroAmount)));
}

#[test]
fn admin_cannot_take_holder_funds() {
    let mut env = Env::new(vec![]);
    let d = sol_setup(&mut env);
    let holder = env.user(SOL);
    env.deposit(&d, 5 * SOL);
    let (root, total, proofs) = tree(&d, &[(holder.pubkey(), 5 * SOL)]);
    env.propose(&d, root, total, 100).unwrap();
    let adm = env.admin.insecure_clone();
    let v0 = env.lamports(&d.vault());
    let a0 = env.lamports(&adm.pubkey());
    // every admin instruction, none moves vault funds
    for data in [
        instruction::SetPaused { paused: true }.data(),
        instruction::SetPaused { paused: false }.data(),
        instruction::ProposeAdmin { new_admin: adm.pubkey() }.data(),
    ] {
        let ix = env.ix_admin(&adm.pubkey(), data);
        env.send(ix, &[&adm]).unwrap();
    }
    env.set_mode(deep_rewards::PAYOUT_MODE_AUTO_SEND);
    assert_eq!(env.lamports(&d.vault()), v0, "settings changes move no funds");
    // the admin cannot publish a root, nor become the root authority
    let (evil_root, _, evil_proofs) = tree(&d, &[(adm.pubkey(), 5 * SOL)]);
    let ix = env.ix_propose(&adm.pubkey(), &d, evil_root, 5 * SOL, 101, [0; 32]);
    assert_eq!(env.send(ix, &[&adm]).map(|_| ()), Err(err(RewardsError::Unauthorized)));
    let ix = env.ix_queue(&adm.pubkey(), params(adm.pubkey(), vec![]));
    assert_eq!(env.send(ix, &[&adm]).map(|_| ()), Err(err(RewardsError::InvalidParams)));
    // claiming without a leaf of its own fails
    assert_eq!(
        env.claim(&adm, &d, 5 * SOL, evil_proofs[&adm.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::InvalidProof))
    );
    assert_eq!(
        env.claim(&adm, &d, 5 * SOL, proofs[&holder.pubkey()].clone()).map(|_| ()),
        Err(err(RewardsError::InvalidProof))
    );
    // pushing the holder's leaf pays the HOLDER, never the caller
    env.set_price(20_000_000_000, 0);
    env.push(&adm, &holder.pubkey(), &d, 5 * SOL, proofs[&holder.pubkey()].clone()).unwrap();
    assert_eq!(env.lamports(&holder.pubkey()), SOL + 5 * SOL);
    assert!(env.lamports(&adm.pubkey()) < a0, "admin only paid fees and rent");
    assert_eq!(env.lamports(&d.vault()), v0 - 5 * SOL);
    // (a direct system transfer out of the vault would need the PDA's signature, which only
    // deep-rewards can produce, and no instruction pays anyone but a verified leaf wallet)
    // a stranger cannot create distributors
    let stranger = env.user(SOL);
    let m2 = Keypair::new();
    env.create_mint(&m2, TOKEN, 6, false);
    let ix = env.ix_init_distributor(&stranger.pubkey(), &Dist::sol(m2.pubkey()));
    assert_eq!(env.send(ix, &[&stranger]).map(|_| ()), Err(err(RewardsError::Unauthorized)));
}

#[test]
fn unsupported_reward_mints_are_refused() {
    let mut env = Env::new(vec![]);
    let mint = Keypair::new();
    env.create_mint(&mint, TOKEN, 6, false);
    // the rewarded token cannot be its own reward asset
    let same = Dist {
        mint: mint.pubkey(),
        reward_mint: mint.pubkey(),
        program: TOKEN,
    };
    let r = env.root.insecure_clone();
    let ix = env.ix_init_distributor(&r.pubkey(), &same);
    assert!(env.send(ix, &[&r]).is_err());
    // Token-2022 non-transferable mint: payouts could never move
    let nt = Keypair::new();
    let payer = env.payer.insecure_clone();
    let len = spl_token_2022::extension::ExtensionType::try_calculate_account_len::<spl_token_2022::state::Mint>(
        &[spl_token_2022::extension::ExtensionType::NonTransferable],
    )
    .unwrap();
    let ixs = vec![
        system_instruction::create_account(&payer.pubkey(), &nt.pubkey(), env.rent(len), len as u64, &TOKEN_2022),
        spl_token_2022::instruction::initialize_non_transferable_mint(&TOKEN_2022, &nt.pubkey()).unwrap(),
        spl_token_2022::instruction::initialize_mint2(&TOKEN_2022, &nt.pubkey(), &payer.pubkey(), None, 6).unwrap(),
    ];
    env.send_ixs(ixs, &[&payer, &nt]).unwrap();
    let d = Dist {
        mint: mint.pubkey(),
        reward_mint: nt.pubkey(),
        program: TOKEN_2022,
    };
    let ix = env.ix_init_distributor(&r.pubkey(), &d);
    assert_eq!(env.send(ix, &[&r]).map(|_| ()), Err(err(RewardsError::UnsupportedRewardMint)));
    // SOL must use the SPL Token program for its WSOL ATA
    let bad = Dist {
        mint: mint.pubkey(),
        reward_mint: NATIVE_MINT,
        program: TOKEN_2022,
    };
    let ix = env.ix_init_distributor(&r.pubkey(), &bad);
    assert!(env.send(ix, &[&r]).is_err());
}

