fn ix_recover(env: &Env, cranker: &Pubkey, mint: &Pubkey, stray_mint: &Pubkey, program: &Pubkey, vault_token: Pubkey) -> Instruction {
    let _ = env;
    Instruction {
        program_id: deep_rewards::ID,
        accounts: accounts::RecoverStray {
            cranker: *cranker,
            config: config_pda(),
            mint: *mint,
            holder_vault: holder_vault(mint),
            reward_distributor: distributor_pda(mint, stray_mint),
            stray_mint: *stray_mint,
            vault_token,
            stray_recipient: STRAY,
            recipient_token: ata(&STRAY, stray_mint, program),
            token_program: *program,
            associated_token_program: ATA_PROGRAM,
            system_program: SYSTEM,
        }
        .to_account_metas(None),
        data: instruction::RecoverStray {}.data(),
    }
}

#[test]
fn recover_stray_moves_non_reward_tokens_and_closes_the_account() {
    let usd = Keypair::new();
    let mut env = Env::new(vec![usd.pubkey()]);
    let d = sol_setup(&mut env); // SOL distributor: lamports + WSOL are reward assets
    env.deposit(&d, SOL);
    let lamports0 = env.lamports(&d.vault());
    let cranker = env.user(SOL);

    // 1. the rewarded token itself, sent to the holder vault (e.g. by mistake, or via deep-amm's
    //    token-side ATA): moved to the stray recipient, the vault's account closed
    let own = env.fund_tokens(&d.vault(), &d.mint, &TOKEN, 1_234_567);
    let rent = env.lamports(&own);
    let ix = ix_recover(&env, &cranker.pubkey(), &d.mint, &d.mint, &TOKEN, own);
    env.send(ix, &[&cranker]).expect("recover the rewarded token");
    assert_eq!(env.token_amount(&ata(&STRAY, &d.mint, &TOKEN)), 1_234_567);
    assert!(env.svm.get_account(&own).is_none(), "emptied vault account closed");
    assert_eq!(env.lamports(&STRAY), rent, "its rent went to the stray recipient");
    assert_eq!(env.lamports(&d.vault()), lamports0, "SOL rewards untouched");

    // 2. a random Token-2022 airdrop with no distributor: recovered too
    let junk = Keypair::new();
    env.create_mint(&junk, TOKEN_2022, 0, false);
    let jt = env.fund_tokens(&d.vault(), &junk.pubkey(), &TOKEN_2022, 42);
    let ix = ix_recover(&env, &cranker.pubkey(), &d.mint, &junk.pubkey(), &TOKEN_2022, jt);
    env.send(ix, &[&cranker]).unwrap();
    assert_eq!(env.token_amount(&ata(&STRAY, &junk.pubkey(), &TOKEN_2022)), 42);

    // 3. reward assets are refused: WSOL (always), a configured stablecoin, a mint with a
    //    distributor for this token
    let wsol = d.token_vault();
    let ix = ix_recover(&env, &cranker.pubkey(), &d.mint, &NATIVE_MINT, &TOKEN, wsol);
    assert_eq!(env.send(ix, &[&cranker]).map(|_| ()), Err(err(RewardsError::NotStray)));
    env.create_mint(&usd, TOKEN, 6, false);
    let ut = env.fund_tokens(&d.vault(), &usd.pubkey(), &TOKEN, 5);
    let ix = ix_recover(&env, &cranker.pubkey(), &d.mint, &usd.pubkey(), &TOKEN, ut);
    assert_eq!(env.send(ix, &[&cranker]).map(|_| ()), Err(err(RewardsError::NotStray)));
    let quote = Keypair::new();
    env.create_mint(&quote, TOKEN, 6, false);
    let qd = Dist {
        mint: d.mint,
        reward_mint: quote.pubkey(),
        program: TOKEN,
    };
    env.init_distributor(&qd);
    env.deposit(&qd, 1_000);
    let ix = ix_recover(&env, &cranker.pubkey(), &d.mint, &quote.pubkey(), &TOKEN, qd.token_vault());
    assert_eq!(env.send(ix, &[&cranker]).map(|_| ()), Err(err(RewardsError::NotStray)));
    assert_eq!(env.token_amount(&qd.token_vault()), 1_000, "reward vault untouched");

    // 4. the destination is only ever config.stray_recipient
    let mut bad = ix_recover(&env, &cranker.pubkey(), &d.mint, &d.mint, &TOKEN, own);
    bad.accounts[7].pubkey = cranker.pubkey();
    assert!(env.send(bad, &[&cranker]).is_err());
}

// ───────────── Security review before mainnet (2026-10-07): F1, the guardian ─────────────

/// F1: a stolen root-authority key publishes a root that moves every unclaimed reward to the
/// thief. The program cannot tell (only the hash is on chain; the total is unchanged and
/// funded), so only a veto within the delay stops it. The guardian vetoes it, at the last
/// second; a stranger and the root authority cannot; the honest holder then claims in full.
#[test]
fn a_malicious_root_is_vetoed_by_the_guardian_and_cannot_be_vetoed_by_a_stranger() {
    let mut env = Env::new(vec![]);
    let d = sol_setup(&mut env);
    let honest = env.user(SOL);
    let thief = env.user(SOL);
    env.deposit(&d, SOL);
    let (root, total, proofs) = tree(&d, &[(honest.pubkey(), SOL)]);
    env.propose(&d, root, total, 100).unwrap();
    assert_eq!(env.distributor(&d).round, 1);

    let (bad, bad_total, bad_proofs) = tree(&d, &[(thief.pubkey(), SOL)]);
    assert_eq!(bad_total, total, "nothing a funding or monotonic check could catch");
    env.propose_pending(&d, bad, bad_total, 101)
        .expect("the program accepts it as pending");
    let dist = env.distributor(&d);
    assert!(dist.has_pending);
    assert_eq!(dist.pending_root, bad);
    assert_eq!(dist.pending_eta, env.now() + DELAY);
    assert_eq!(DELAY, 12 * 3600, "the delay leaves a person time to act: at least 12 h");
    // it is never active at once, whatever the delay: activation is a separate instruction
    assert_eq!(dist.root, root);
    let anyone = env.user(SOL);
    assert_eq!(
        env.send(env.ix_activate(&d), &[&anyone]).map(|_| ()),
        Err(err(RewardsError::RootNotReady))
    );

    // a stranger, the root authority and the thief cannot veto
    let stranger = env.user(SOL);
    let root_kp = env.root.insecure_clone();
    for who in [&stranger, &root_kp, &thief] {
        assert_eq!(
            env.send(env.ix_veto(&who.pubkey(), &d), &[who]).map(|_| ()),
            Err(err(RewardsError::Unauthorized))
        );
    }
    assert!(env.distributor(&d).has_pending);

    // the guardian (not the admin) vetoes one second before the root could activate
    env.advance(DELAY - 1);
    let g = guardian_kp();
    env.svm.airdrop(&g.pubkey(), SOL).unwrap();
    assert_ne!(g.pubkey(), env.admin.pubkey());
    let v0 = env.lamports(&d.vault());
    env.send(env.ix_veto(&g.pubkey(), &d), &[&g])
        .expect("the guardian vetoes");
    assert_eq!(env.lamports(&d.vault()), v0, "a veto moves no funds");
    let dist = env.distributor(&d);
    assert!(!dist.has_pending);
    assert_eq!((dist.round, dist.root), (1, root), "the honest root stays active");

    // the bad root can never activate, the thief's leaf is worthless, the honest holder is paid
    env.advance(DELAY);
    assert_eq!(
        env.send(env.ix_activate(&d), &[&anyone]).map(|_| ()),
        Err(err(RewardsError::NoPendingRoot))
    );
    assert_eq!(
        env.claim(&thief, &d, SOL, bad_proofs[&thief.pubkey()].clone())
            .map(|_| ()),
        Err(err(RewardsError::InvalidProof))
    );
    env.claim(&honest, &d, SOL, proofs[&honest.pubkey()].clone())
        .expect("the honest holder claims");
    let dist = env.distributor(&d);
    assert_eq!(dist.total_claimed, SOL);
    assert_eq!(
        env.lamports(&d.vault()),
        dist.vault_reserve,
        "the vault is drained exactly to its reserve"
    );
}

/// F1: the guardian can veto and pause, nothing else, and it changes only through the delayed
/// settings change.
#[test]
fn the_guardian_can_veto_and_pause_and_nothing_else() {
    let mut env = Env::new(vec![]);
    let d = sol_setup(&mut env);
    let a = env.admin.insecure_clone();
    let g = guardian_kp();
    env.svm.airdrop(&g.pubkey(), 10 * SOL).unwrap();
    let c: RewardsConfig = env.load(&config_pda());
    assert_eq!(c.guardian, g.pubkey());
    let stranger = env.user(SOL);
    let root_kp = env.root.insecure_clone();

    // pause: the admin and the guardian; not a stranger, not the root authority
    for who in [&stranger, &root_kp] {
        assert_eq!(
            env.send(env.ix_set_paused(&who.pubkey(), true), &[who]).map(|_| ()),
            Err(err(RewardsError::Unauthorized))
        );
    }
    env.send(env.ix_set_paused(&g.pubkey(), true), &[&g])
        .expect("the guardian pauses");
    assert!(env.load::<RewardsConfig>(&config_pda()).paused);
    env.deposit(&d, SOL);
    let holder = env.user(SOL);
    let (root, total, proofs) = tree(&d, &[(holder.pubkey(), SOL)]);
    assert_eq!(
        env.propose_pending(&d, root, total, 100).map(|_| ()),
        Err(err(RewardsError::Paused)),
        "no root can be published while paused"
    );
    env.send(env.ix_set_paused(&g.pubkey(), false), &[&g])
        .expect("the guardian resumes");
    env.propose(&d, root, total, 100).unwrap();
    // claims are never paused, also not by the guardian
    env.send(env.ix_set_paused(&g.pubkey(), true), &[&g]).unwrap();
    env.claim(&holder, &d, SOL, proofs[&holder.pubkey()].clone())
        .expect("claim while paused");
    env.send(env.ix_set_paused(&a.pubkey(), false), &[&a])
        .expect("the admin resumes");

    // everything else is refused to the guardian
    let p = env.current_params();
    assert_eq!(
        env.send(env.ix_queue(&g.pubkey(), p.clone()), &[&g]).map(|_| ()),
        Err(err(RewardsError::Unauthorized))
    );
    assert_eq!(
        env.send(env.ix_cancel(&g.pubkey()), &[&g]).map(|_| ()),
        Err(err(RewardsError::Unauthorized))
    );
    let ix = env.ix_admin(
        &g.pubkey(),
        instruction::ProposeAdmin { new_admin: g.pubkey() }.data(),
    );
    assert_eq!(env.send(ix, &[&g]).map(|_| ()), Err(err(RewardsError::Unauthorized)));
    let ix = env.ix_propose(&g.pubkey(), &d, [9; 32], SOL, 200, [0; 32]);
    assert_eq!(env.send(ix, &[&g]).map(|_| ()), Err(err(RewardsError::Unauthorized)));
    let m2 = Keypair::new();
    env.create_mint(&m2, TOKEN, 6, false);
    let ix = env.ix_init_distributor(&g.pubkey(), &Dist::sol(m2.pubkey()));
    assert_eq!(env.send(ix, &[&g]).map(|_| ()), Err(err(RewardsError::Unauthorized)));

    // a guardian is mandatory and is never the root authority
    for bad in [Pubkey::default(), p.root_authority] {
        let mut q = p.clone();
        q.guardian = bad;
        assert_eq!(
            env.send(env.ix_queue(&a.pubkey(), q), &[&a]).map(|_| ()),
            Err(err(RewardsError::InvalidParams))
        );
    }
    // it changes only through the delayed settings change: the old one keeps its power until
    // the delay has passed, then loses it
    let new_g = env.user(SOL);
    let mut q = p.clone();
    q.guardian = new_g.pubkey();
    env.send(env.ix_queue(&a.pubkey(), q), &[&a]).unwrap();
    assert_eq!(
        env.send(env.ix_set_paused(&new_g.pubkey(), true), &[&new_g]).map(|_| ()),
        Err(err(RewardsError::Unauthorized)),
        "not before the delay"
    );
    env.advance(DELAY);
    let anyone = env.user(SOL);
    env.send(env.ix_apply(), &[&anyone]).unwrap();
    assert_eq!(env.load::<RewardsConfig>(&config_pda()).guardian, new_g.pubkey());
    assert_eq!(
        env.send(env.ix_set_paused(&g.pubkey(), true), &[&g]).map(|_| ()),
        Err(err(RewardsError::Unauthorized)),
        "the replaced guardian has no power left"
    );
    env.send(env.ix_set_paused(&new_g.pubkey(), true), &[&new_g])
        .expect("the new guardian pauses");
}

/// The devnet upgrade path: a RewardsConfig and a PendingRewardsConfig written before the
/// guardian existed. `migrate_config` (anyone, idempotent) grows the pending account, clears
/// stale bytes, raises the root delay to the new minimum, and sets no guardian; a change
/// queued before the upgrade cannot be applied and is queued again.
#[test]
fn migrate_config_brings_a_pre_guardian_deployment_to_the_current_rules() {
    use anchor_lang::AnchorSerialize;
    let stable = Pubkey::new_from_array([0x51; 32]);
    let mut env = Env::new(vec![stable]);
    let a = env.admin.insecure_clone();
    let cfg_key = config_pda();
    let pend_key = pending_pda();

    // RewardsConfig as the previous build left it: 1 h delay, 64 reserved zero bytes
    let mut acc = env.svm.get_account(&cfg_key).unwrap();
    let n = acc.data.len();
    assert_eq!(n, 390);
    acc.data[n - 64..].fill(0);
    acc.data[108..112].copy_from_slice(&3600u32.to_le_bytes());
    env.svm.set_account(cfg_key, acc).unwrap();
    let c: RewardsConfig = env.load(&cfg_key);
    assert_eq!((c.root_delay_seconds, c.guardian), (3600, Pubkey::default()));
    assert_eq!(c.stray_recipient, STRAY);

    // PendingRewardsConfig in the old 280-byte layout, holding an ACTIVE queued change and,
    // after it, stale bytes of an older, longer value
    let new_root = Pubkey::new_from_array([0x52; 32]);
    let old_acc = env.svm.get_account(&pend_key).unwrap();
    assert_eq!(old_acc.data.len(), 312);
    let queued = deep_rewards::PendingRewardsConfigV1 {
        bump: old_acc.data[8],
        active: true,
        eta: NOW + 3600,
        queued_at: NOW,
        params: deep_rewards::RewardsConfigParamsV1 {
            root_authority: new_root,
            payout_mode: deep_rewards::PAYOUT_MODE_AUTO_SEND,
            root_delay_seconds: 3600,
            max_proof_len: 20,
            push_min_usd_micros: 7_000_000,
            min_holding_usd_micros: 8_000_000,
            max_price_age_seconds: 90,
            sol_usd_price_update: PYTH,
            stable_mints: vec![stable],
            stray_recipient: STRAY,
        },
    };
    let mut data = old_acc.data[..8].to_vec();
    queued.serialize(&mut data).unwrap();
    let used = data.len();
    data.resize(280, 0xAB);
    let lamports = env.rent(280);
    env.svm
        .set_account(
            pend_key,
            solana_account::Account {
                lamports,
                data,
                owner: deep_rewards::ID,
                executable: false,
                rent_epoch: 0,
            },
        )
        .unwrap();

    // before the migration the three settings instructions fail closed: the stale bytes are
    // never read as a guardian
    let anyone = env.user(SOL);
    env.advance(3600);
    assert_eq!(
        env.send(env.ix_apply(), &[&anyone]).map(|_| ()),
        Err(err(RewardsError::ConfigNotMigrated))
    );
    assert_eq!(
        env.send(env.ix_cancel(&a.pubkey()), &[&a]).map(|_| ()),
        Err(err(RewardsError::ConfigNotMigrated))
    );
    let wanted = params(env.root.pubkey(), vec![stable]);
    assert_eq!(
        env.send(env.ix_queue(&a.pubkey(), wanted.clone()), &[&a]).map(|_| ()),
        Err(err(RewardsError::ConfigNotMigrated))
    );
    // the admin can veto and pause meanwhile (no guardian is set yet)
    env.send(env.ix_set_paused(&a.pubkey(), true), &[&a]).unwrap();
    env.send(env.ix_set_paused(&a.pubkey(), false), &[&a]).unwrap();
    let nobody = env.user(SOL);
    assert_eq!(
        env.send(env.ix_set_paused(&nobody.pubkey(), true), &[&nobody]).map(|_| ()),
        Err(err(RewardsError::Unauthorized)),
        "an unset guardian matches no signer"
    );

    // migrate: anyone, paying exactly the rent difference
    let stranger = env.user(SOL);
    let s0 = env.lamports(&stranger.pubkey());
    env.send(env.ix_migrate(&stranger.pubkey()), &[&stranger])
        .expect("migrate_config");
    assert_eq!(
        s0 - env.lamports(&stranger.pubkey()),
        env.rent(312) - env.rent(280) + 5_000
    );
    let acc = env.svm.get_account(&pend_key).unwrap();
    assert_eq!(acc.data.len(), 312);
    assert_eq!(acc.lamports, env.rent(312));
    assert!(
        acc.data[used + 32..].iter().all(|b| *b == 0),
        "stale bytes are gone"
    );
    let pend: deep_rewards::PendingRewardsConfig = env.load(&pend_key);
    assert!(pend.active);
    assert_eq!((pend.eta, pend.queued_at), (NOW + 3600, NOW));
    assert_eq!(pend.bump, queued.bump);
    assert_eq!(pend.params, queued.params.clone().with_guardian(Pubkey::default()));
    let c: RewardsConfig = env.load(&cfg_key);
    assert_eq!(c.root_delay_seconds, deep_rewards::MIN_ROOT_DELAY_SECONDS);
    assert_eq!(c.guardian, Pubkey::default(), "the migration sets no guardian");
    assert_eq!(c.root_authority, env.root.pubkey(), "nothing else changed");
    assert_eq!(c.stray_recipient, STRAY);

    // idempotent: a second call changes nothing and costs only the network fee
    let before = (
        env.svm.get_account(&pend_key).unwrap().data,
        env.svm.get_account(&cfg_key).unwrap().data,
    );
    let s1 = env.lamports(&stranger.pubkey());
    env.send(env.ix_migrate(&stranger.pubkey()), &[&stranger])
        .expect("migrate_config again");
    assert_eq!(s1 - env.lamports(&stranger.pubkey()), 5_000);
    assert_eq!(
        before,
        (
            env.svm.get_account(&pend_key).unwrap().data,
            env.svm.get_account(&cfg_key).unwrap().data,
        )
    );

    // the change queued before the upgrade has no guardian: it cannot be applied ...
    assert_eq!(
        env.send(env.ix_apply(), &[&anyone]).map(|_| ()),
        Err(err(RewardsError::InvalidParams))
    );
    assert_eq!(env.load::<RewardsConfig>(&cfg_key).root_authority, env.root.pubkey());
    // ... the admin cancels it and queues the settings again, now with a guardian, which
    // waits the (raised) delay
    env.send(env.ix_cancel(&a.pubkey()), &[&a]).unwrap();
    env.send(env.ix_queue(&a.pubkey(), wanted.clone()), &[&a]).unwrap();
    env.advance(DELAY - 1);
    assert_eq!(
        env.send(env.ix_apply(), &[&anyone]).map(|_| ()),
        Err(err(RewardsError::ConfigUpdateNotReady))
    );
    env.advance(1);
    env.send(env.ix_apply(), &[&anyone]).unwrap();
    let c: RewardsConfig = env.load(&cfg_key);
    assert_eq!(c.guardian, guardian_kp().pubkey());
    let g = guardian_kp();
    env.svm.airdrop(&g.pubkey(), SOL).unwrap();
    env.send(env.ix_set_paused(&g.pubkey(), true), &[&g])
        .expect("the guardian has its power");
}
